INSERT INTO passages (title, content, language, exam_type, difficulty, source_note, char_count, word_count)
VALUES
('సర్వీసుల సమాచార కార్యాలయంలో సమాచార హక్కు ప్రకటన', 'సర్వీసుల సమాచార కార్యాలయం రాష్ట్ర సమాచార హక్కు చట్టం ప్రకారం సర్వీసులకు సంబంధించిన సమాచారం అందించడం గురించి ఒక ప్రకటన జారీ చేసింది. ఆవర్తన ప్రక్రియలో ఉద్దేశించిన పనులను పూర్తి చేసిన వ్యక్తులకు సంబంధించిన సమాచారాన్ని వెంటనే అందించాలని కార్యాలయానికి ఆదేశించారు. అధికారికి ఏ కార్యాలయంలో అనుసంధానం చేయాలో, ఏ రోజు ఉదయం ఏ సమయానికి వెళ్లాలో, ఎంత సమయం పట్టుకోవాలో అనే విషయాలు అర్హులైన వారికి తెలియజేయాలని కోరారు. సమాచారం ఇవ్వడంలో ఏ అధికారికి ఏ ఆధారాలు కావాలో అనేది జాబితాలో ఇవ్వబడింది. ఆవర్తన ప్రక్రియ సంబంధించిన వివరాలను నిల్వ చేసి ఉంచాలని, ఆ వివరాలను నిర్దిష్ట గడువు లోపు అందించాలని కార్యాలయానికి సూచించారు. ఏ కార్యాలయం ఏ అధికారిని సంప్రదించాలో ఏ గడువు లోపు వారి ప్రమతిని రాసి ఇవ్వాలో కూడా తెలియజేయాలని ఆదేశించారు.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 619, 90),
('పరీక్షల సమయ పట్టిక పునరుద్ధరణపై ప్రకటన', 'పరీక్షల కార్యాలయం వచ్చే శాసన సంస్థ ఎంపికల పరీక్షల కు సంబంధించిన సమయ పట్టికను పునరుద్ధరించి ప్రకటన జారీ చేసింది. నిర్ణీత తేదీల్లో పరీక్షలు రెండు సెషన్లలో నిర్వహించబడుతాయి. మొదటి సెషన్ ఉదయం ఎనిమిది గంటలకు, రెండో సెషన్ మధ్యాహ్నం ఒక గంటకు నిర్వహించబడుతాయి. అభ్యర్థులు గుర్తింపు చేసుకోవడానికి ప్రారంభ సమయానికి ముప్పై నిమిషాల ముందు కేంద్రానికి చేరుకోవాలి. గుర్తింపు చేసుకునే సమయంలో గుర్తింపు పత్రం మరియు ప్రవేశపత్రాన్ని అధికారులు సరిచూస్తారు. తవ్వలు మూసివేసిన తర్వాత వచ్చే అభ్యర్థులకు పరీక్షలో హాజరయ్యే అనుమతి ఇవ్వబడదు. పరీక్షల హాలులో చేతిలో పెన, పెన్సిల్ తీసుకురావాలని అభ్యర్థులకు సూచించారు. పరీక్షా జరిగే గదిలో ఎలాంటి ఎలక్ట్రానిక్ పరికరాలు లేవని తెలియజేశారు.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 579, 76),
('కార్యాలయ సామగ్రి మరమ్మతుల గురించి సూచన', 'సాధారణ నిర్వహణ విభాగం విభాగంలోని అన్ని శాఖలలో కార్యాలయ సామగ్రిని మరమ్మత చేయడం గురించి సూచన జారీ చేసింది. ప్రతి నెల పదో నుండి ఇరవైవ తేదీల మధ్య ప్రతి కార్యాలయాన్ని సాంకేతిక బృందం సందర్శించి టైప్‌రైటర్లు, డూప్లికేటింగ్ యంత్రాలు మరియు ఇతర సామగ్రి పరిశీలనా చేస్తారు. సందర్శనకు ముందు సామగ్రి స్థితిని లిఖితంగా విభాగానికి తెలియజేయాలని ప్రతి కార్యాలయ ఉద్యోగులకు తెలిపారు. ఆర్థికంగా పునరుద్ధరించడం సాధ్యం కాని యంత్రాలను జాబితాపరచి కేంద్రీయ మరమ్మత కార్మికశాలకు పంపుతారు. సామగ్రి యొక్క వారంటీ రద్దు కాకుండా ఉండాలని, ఉద్యోగులు స్వయంగా మరమ్మత చేయవద్దని విభాగం కోరింది. పరిశీలనలో వినియోగించిన వినియోగ వస్తువుల ఖర్చు సంబంధిత శాఖ కార్యాలయ బడ్జెట్ నుండి వసూలు చేయబడుతుంది.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 577, 79),
('నీటి సరఫరా అంతర్గామి గురించి ప్రకటన', 'నగరపాలిక కార్యాలయం ప్రాంత వాసులకు సమాచారం ఇచ్చింది. మార్కెట్ క్రాసింగ్ దగ్గర ప్రధాన పైప్‌లైన్ మరమ్మత కారణంగా నగరంలో పైప్ నీటి రెండు రోజుల పాటు నిలిపివేయబడుతుంది. మొదటి రోజు ఉదయం నుండి రెండో రోజు సాయంత్రం వరకు నీటి సరఫరా నిలిపివేయబడుతుంది. ఈ సమయంలో కార్యాలయం రెండు చోట్ల ట్యాంకర్ల ద్వారా తాత్కాలిక సరఫరాను ఏర్పాటు చేస్తుంది. మొదటి ట్యాంకరు ఉదయం పబ్లిక్ వెల్ల వద్ద, రెండో ట్యాంకరు మధ్యాహ్నం ఆలయ ద్వారం వద్ద ఉంటుంది. సరఫరా నిలిపివేయడానికి ముందు వారసులు రెండు రోజులకు తగిన నీటిని సేకరించుకోవాలని కోరారు. మరమ్మత పని ఆలస్యం కాకుండా గల్లులలో పైప్‌లైన్లు స్వచ్ఛంగా ఉంచాలని కార్యాలయం వాసులను కోరింది. పని పూర్తయిన వెంటనే సరఫరా పునరుద్ధరించబడుతుంది.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 559, 81),
('పబ్లిక్ గ్రంథాలయ సంరక్షణ గురించి ప్రకటన', 'పబ్లిక్ గ్రంథాలయ కమిటీ వచ్చే నెలలో చదవున ప్రాంగణం మరియు పుస్తక అరల గదులకు పూర్తి పరిశుభత చేయించాలని నిర్ణయించింది. నెల ఆరో తారీఖు నుండి ఇరవై తారీఖు వరకు ప్రజలకు గ్రంథాలయం మూసివేయబడుతుంది. ఈ కాలంలో పుస్తకాలు తీసుకోవాలనుకునే సభ్యులు ముందుగా కమిటీ కార్యాలయంలో అభ్యర్థన చేయాలని కోరారు. పుస్తకాల ఇవ్వడం పక్కవైపు ద్వారం కౌంటర్ ద్వారా ఉదయం పది నుండి మధ్యాహ్నం నాలుగు వరకు కొనసాగుతుంది. చెడిపోయిన కాషాయ గురులు మరియు చదవడానికి దీపాలను కమిటీ మరమ్మత చేయాలని నిర్ణయించింది. పాఠకులు గొంతు లేదా వాయుస్థిరత్వాన్ని పాటించాలని, టేబులు స్వచ్ఛంగా ఉంచాలని కోరారు.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 476, 68),
('నెమునిక రిపోర్ట్ సమర్పణపై సూచనలు', 'విభాగం అధీనస్థ కార్యాలయాల నెమునిక రిపోర్ట్ సమర్పణ గురించి సూచనలు జారీ చేసింది. ఒక నెల రిపోర్ట్ తదుపరి నెల ఐదో కార్య దినానికి ప్రధాన కార్యాలయానికి చేరుకోవాలి. ఈ సూచనలకు అనుబంధించిన నమూనాలో రిపోర్ట్ రూపొందించాలి, అందులో పని పురోగతి, ఖర్చు చేసిన మొత్తం మరియు ఇంకా పెండింగ్‌లో ఉన్న విషయాలు ఉండాలి. ప్రతి నెల పదో కార్య దినానికి నెమునిక సమీక్ష సమావేశం నిర్వహించబడుతుంది. సమయంలో రిపోర్ట్ సమర్పించలేకపోయే కార్యాలయాలు మూడో కార్య దినానికి లిఖిత వివరణ ప్రధాన కార్యాలయానికి పంపాలి. వార్షిక రిపోర్ట్ నెమునిక రిపోర్ట్ల నుండి సిద్ధమవుతుంది, కాబట్టి నెమునిక రిపోర్ట్లు పూర్తి మరియు ఖచ్చితంగా ఉండాలి.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 511, 73),
('గ్రామ ఆరోగ్య సమితి కార్యాచరణపై దిశానిర్దేశాలు', 'విభాగం కార్యక్రమంలో భాగంగా ఉన్న గ్రామాల్లోని గ్రామ ఆరోగ్య సమితుల కార్యాచరణ కోసం దిశానిర్దేశాలు జారీ చేసింది. సమితిలో ఏడు మందికంటే తక్కువ కాకుండా పదకొండు మందికంటే ఎక్కువ కాకుండా సభ్యులు ఉండాలి, అందులో కనీసం మూడో భాగం మహిళలు ఉండాలి. సమితి నెలకు ఒకసారి సమావేశం కలుగుతూ, సమావేశం వివరాలు రిజిస్టర్‌లో నమోదు చేసి పర్యవేక్షకుడికి చూపించాలి. సమితి గ్రామంలోని గృహ సమీక్ష జాబితా, సహాయం అవసరమైన గృహాల జాబితా రూపొందించాలి, వైద్య సహాయం అవసరమైన సంఘటనలను ఆరోగ్య కేంద్రానికి పంపాలి. పిల్లల పెరుగుదల రిజిస్టర్ ప్రతి నెల నవీకరించాలి. సమితికి ఇవ్వబడిన నిధులు గ్రామ పరిశుభ్రత మరియు పిల్లల పోషణ కోసం వినియోగించాలి.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 519, 75),
('హస్తి పంపు మరమ్మత పై సూచన', 'గ్రామీణ నీటి సరఫరా విభాగం ప్రాథమిక పాఠశాల ముగ్గులో ఉన్న హస్తి పంపును మరమ్మత చేయబోతుంది. పంపు రెండు కార్య దినాల పాటు వాడకుండా ఉంటుంది, విభాగం పాఠశాల ద్వారం దగ్గర ఉన్న బావిలో తాత్కాలిక నీటి స్థలాన్ని ఏర్పాటు చేసింది. పంపు హ్యాండిల్ ఘనం పడిపోవడంతో, నీటి ప్రవాహం బలహీనంగా ఉన్నందున మరమ్మత అవసరం. మరమ్మత సమయంలో ఉపయోగకర్తలు పంపును బలంగా తిప్పకూడదని విభాగం కోరింది, ఎందుకంటే కొత్త భాగాలు దెబ్బతినగలవు. స్థానిక పాఠశాల నిర్వహణకు తాత్కాలిక ఏర్పాట్ల గురించి తెలియజేయబడింది. పని పూర్తయిన తర్వాత ఇంజనీరు పరిశీలన చేస్తారు, పరిశీలన సంతోషకరంగా ఉంటే అదే రోజు పంపును తెరుచుకుంటారు.', 'TE', 'GENERAL', 'EASY', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 491, 72),
('భూసకల వాటిస్తర సంకలనంపై దిశానిర్దేశాలు', 'రాజస్వ విభాగం రోడు విస్తరణ కోసం సేకరించిన భూమి కొరకు నష్టపరిహారం చెల్లింపుపై ప్రకటన జారీ చేసింది. కలేక్టరు నిర్ణయించిన నష్టపరిహారం విలువ ప్రకటనలో ప్రచురించబడింది మరియు అంచనా విలువను ఉప కలేక్టరు కార్యాలయంలో పరిశీలన కోసం అందుబాటులో ఉంది. అంచనాపై సంతృప్తి లేనివారు ప్రచురణకు ముప్పై రోజుల లోపు తమ వద్ద ఉన్న పత్రాలతో లిఖిత ఆక్షేపన ప్రదేశించవచ్చు. ఆక్షేపనలో అసంతృప్తి కారణం మరియు కోరుతున్న నివారణ ఉండాలి, అది ప్రాంత ఉప కలేక్టరు పేరున ఉండాలి. రాజస్వ బోర్డు ఆక్షేపనలను పరిశీలించి అరవై రోజుల్లో తుది నిర్ణయం జారీ చేస్తుంది. నష్టపరిహారం రెండు కిస్తుల్లో చెల్లించబడుతుంది, మొదటి కిస్తి ప్రతిభూతి ఆమోదనపై, రెండో కిస్తి భూమి అప్పాదం అపర్పించిన తర్వాత. తుది నిర్ణయం తర్వాత మరేదైనా మొత్తం దావదావును ఆక్షేపించుకోవడం ఆమోదించబడదు.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 625, 88),
('ఉపాధి లైసెన్స్ జారీ సూచనలపై సర్కులర్', 'నగర కమిషనర్ కార్యాలయం రాబోటీ సంవత్సరానికి ఉపాధి లైసెన్స్ జారీ మరియు పునరుద్ధరణ గురించి సూచనలు జారీ చేసింది. నగర పరిధిలో వ్యాపారం చేసే ప్రతి వ్యాపారి సరైన లైసెన్స్ కలిగి ఉండాలి మరియు లైసెన్స్ కోసం దరఖాస్తు నిర్ణీత తేదీలోపు కార్యాలయానికి చేరుకోవాలి. నిర్ణీత తేదీ తర్వాత దరఖాస్తు చేసినందుకు ప్రతి నెల ఆలస్యానికి జురిమానా వర్తించబడుతుంది, అది వార్షిక లైసెన్స్ సుందరపై లెక్కించబడుతుంది. వ్యాపారం స్వభావాన్ని మార్చుకున్న వారు లేదా స్థానాన్ని మార్చుకున్న వారు మార్పులో ముప్పై రోజుల లోపు కొత్త లైసెన్స్ కోసం దరఖాస్తు చేయాలి. లైసెన్స్ జారీకి ముందు కార్యాలయం ప్రాంగణాన్ని తనిఖీ చేస్తుంది, ప్రాంగణంలో ఆరోగ్య శాఖ యొక్క పరిశుభ్రత సర్టిఫికెట్ ఉండాలి. సరైన లైసెన్స్ లేకుండా వ్యాపారం చేసే వారిపై సరుకు వసూలు మరియు చట్టం ప్రకార శిక్ష అర్హులు.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 635, 91),
('వ్యవసాయ లైసెన్స్ జారీకి సూచనలు', 'మునిసిపల్ కమిషనర్ కార్యాలయం వ్యవసాయ లైసెన్స్ జారీ మరియు నవీకరణ గురించి సూచనలు జారీ చేసింది. నగర పరిధిలో వ్యాపారం చేసే ప్రతి వ్యాపారి సరైన లైసెన్స్ కలిగి ఉండాలి, లైసెన్స్ కోసం దరఖాస్తు నిర్ణీత తేదీలోపు కార్యాలయానికి చేరుకోవాలి. నిర్ణీత తేదీ తర్వాత దాఖలు చేసినవారికి ప్రతి నెల ఆలస్యానికి జురిమానా వర్తించబడుతుంది, అది సంవత్సరపు లైసెన్స్ ఫీజుపై లెక్కించబడుతుంది. తమ వ్యాపార స్వభావాన్ని మార్చుకున్న వారు లేదా స్థానాన్ని మార్చుకున్న వారు మార్పులో ముప్పై రోజుల లోపు కొత్త లైసెన్స్ కోసం దరఖాస్తు చేయాలి. లైసెన్స్ జారీ ముందు కార్యాలయం ప్రాంగణాన్ని తనిఖీ చేస్తుంది, అందులో ఆరోగ్య శాఖ యొక్క పరిశుభ్రత సర్టిఫికెట్ ఉండాలి. లైసెన్స్ లేకుండా వ్యాపారం చేసే వారి సరుకులను నిలిపివేసి, చట్టం ప్రకారం శిక్ష వర్తింపజేయాలని ఆదేశించారు. లైసెన్స్ జారీ నుండి ఒక సంవత్సరం పాటు సరైనదిగా ఉండాలి, అది తనిఖీ కోసం ఉంచాలి.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 692, 100),
('నిర్మాణ స్థలాల్లో ప్రమాదాల నివేదికపై సర్కులర్', 'విభాగం ఆధీనంలోని ఏ నిర్మాణ స్థలంలో జరిగిన ప్రమాదమైనా ప్రధాన కార్యాలయానికి జరిగిన రెండు గంటల్లోగా నివేదిక చేయాలని సర్కులర్ జారీ చేసింది. నివేదికలో ప్రమాద స్థలం, గాయ ప్రకరం, ప్రభావిత వ్యక్తుల సంఖ్య, స్థలంలో అందించిన ప్రథమ చికిత్స వివరాలు ఉండాలి. ఒక వ్యక్తి మరణించిన ప్రమాదాలు లేదా పదిహేదు రోజుల కంటే ఎక్కువ పని నుండి తిరిగి రాలేనంత తీవ్ర గాయం పట్టిన ప్రమాదాలు ఆ రోజే టెలిగ్రామ్ ద్వారా నివేదిక చేయాలి. నివేదిక తర్వాత మూడు రోజుల లోపు నిర్ణీత ఫారంపై వివరణాత్మక స్పష్టీకరణ పంపాలి. స్థలానికి ఆధారి అధికారి ఈ నివేదికకు బాధ్యుడు, తదుపరి తనిఖీ సమయంలో సహాయక అధికారి దీన్ని నిర్ధారిస్తాడు. నిర్ణీత సమయంలో నివేదిక చేయకపోవడాన్ని తీవ్ర ధర్మవ్యత్తి గుర్తించబడుతుంది.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 567, 84),
('జనశికాయత విభాగంలో గ్రామీణ మండలి వైద్యశాల కార్యకలాపాల సమీక్ష', 'విభాగం జనశికాయత విభాగంలోని గ్రామీణ మండలి వైద్యశాలల కార్యకలాపాలను సమీక్షించాలని నిర్ణయించింది. ప్రతి మండలి వైద్యశాలలో సమీక్ష బృందం ఉండాలి, బృందంలో ఒక వైద్యుడు, ఒక సమాజ కార్యకర్త మరియు ఒక గ్రామ స్థాయి ఆద్యమికుడు ఉండాలి. బృందం మూడు నెలలకు ఒకసారి స్థలికి వెళ్లి, ఆశ్రయ విభాగాలలో జరిగే కార్యకలాపాలను తనిఖీ చేయాలి, నర్సులకు ఇచ్చే ఉపాధి లేకపోవడం, మందులు లేకపోవడం లేదా శిక్షణ లేకపోవడం వంటి లోపాలను గుర్తించాలి. గుర్తించిన లోపాలను వెంటనే సరిచేయాలి, లోపాలు ఉన్న సమాజ కార్యకర్తను మార్చి శిక్షణ ఇవ్వాలి. సమీక్ష బృందం నివేదికను జిల్లా వైద్య అధికారికి పంపాలి, నివేదికలో గుర్తించిన లోపాలు, వాటికి సరిచేయడానికి తీసుకున్న చర్య మరియు ఖర్చు అంచేవా ఉండాలి.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 557, 80),
('గ్రామ సభ వేసవులు వెంటనే జరిగేలా చేయడం గురించి ఉపాధి', 'ఉపాధి, గ్రామీణ భావన, పంచాయతీ రాజ్, గ్రామ స్థానిక సర్పంచ్ కార్యాలయాల సమన్వయంతో గ్రామ సభ వేసవులను వెంటనే జరిపేలా చేయడం గురించి ఉపాధి జారీ చేశారు. గ్రామ సభలు ప్రతి గ్రామంలో ఆరు నెలలకు ఒకసారి జరిగేలా, గ్రామ సర్పంచ్ అధ్యక్షతన జరిగేలా చేయడం ఈ ఉపాధి లక్ష్యం. గ్రామ సభలో ప్రజా భాగస్వామ్యం పెరిగేలా, గ్రామ సభల విషయాలపై చర్చకు అవకాశం ఉండేలా, గ్రామంలోని బదిలీ సభ్యులు ఎక్కువ వచ్చేలా చేయడం ఇందులో ఉంది. వీటిని నిర్వహించేందుకు ఉపాధి యొక్క ప్రాధాన లక్ష్యం. గ్రామ సభల విషయాలను గ్రామసభలకు తెలియజేయడం, గ్రామల్లో జరిగే శిక్షణ కార్యక్రమాలను గ్రామ సభ వేసవుల్లో చేర్చడం, గ్రామ ప్రజల నుండి సమస్యలను సేకరించడం వంటివి ఈ ఉపాధి లక్ష్యాలు. గ్రామ సభ వేసవులకు సంబంధించిన ప్రణాళికలను గ్రామ సర్పంచ్ సమన్వయంతో, ఉపాధి అధికారుల సమన్వయంతో ఏర్పాటు చేయాలి.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 624, 96),
('నిర్మాణ క్షేత్రాల్లో కార్మికులకు భద్రతా పరిశీలన', 'నిర్మాణ స్థలాల్లో పని చేసే కార్మికుల భద్రతను నిర్ధారించడం కోసం ఉపాధి, భవన నిర్మాణ శాఖ కార్యాలయం సంయుక్తంగా ఒక కార్యక్రమాన్ని నిర్వహిస్తోంది. ఈ కార్యక్రమం ప్రధానంగా క్షేత్రాల్లో పని చేసే కార్మికులకు ఎత్తివేత, ప్రాథమిక చికిత్స, అగ్ని సంరక్షణ పరికరాలు, సురక్షిత గాడితివారణలు మరియు వ్యక్తిగత రక్షణ సాధనాల అందుబాటులో వితరణపై దృష్టి పెడుతుంది. ఏ స్థలంలో ఏ కార్మికులు పని చేస్తున్నారో, వారి వయస్సు మరియు పని స్వభావం ఏమిటో గుర్తించడం, వారికి శిక్షణ ఇవ్వడం, యాంత్రిక పరికరాలను సురక్షితంగా ఉపయోగించడం వంటి విషయాల్లో జాగ్రత్త తీసుకోవడం ఈ పరిశీలనలో ముఖ్యమైన భాగం. నిర్మాణ సంస్థల అధికారులు ఈ సూచనలను పాటించాలి, లేదా వారి వైపు నుండి జరిగే ప్రమాదాలకు వ్యక్తిగత బాధ్యత ఉంటుంది.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 579, 83),
('వ్యవసాయ వ్యాపారంలో ఎగతాళి లెక్కింపు', 'వ్యవసాయ వ్యాపారంలో ఎగతాళి లెక్కింపు నిర్వహించడం గురించి ఉపాధి జారీ చేసింది. ఎగతాళి లెక్కింపు అంటే ఏ గుత్తులు, ఎంత వస్తువు, ఎప్పుడు కొన్నారు, ఎక్కడ నిల్వ ఉంది, ఎంత నష్టం వచ్చింది, కొన్నవారు ఎవరు, అమ్మేవారు ఎవరు అనే విషయాలను విడిగా నమోదు చేసి ఏర్పాట్లు చేయడం. సాధారణంగా ఎగతాళి లెక్కింపు ఏడు సంవత్సరాలు జరిగిన లెక్కలపై ఆధారంగా జరుగుతుంది, ఇది గ్రామ రికార్డుల సమీక్ష కోసం అవసరం. ఈ లెక్కింపు గ్రామ రికార్డు ఆధారంగా, ఆధారాలు, గ్రామ రికార్డు గుర్తింపు, వ్యాపారం ఏర్పాటు చేసిన స్థలం, మూలం, రుణం మరియు ఇతర వివరాలను నమోదు చేస్తుంది. ఈ లెక్కింపులో భూమి వివరాలు ఉండవు. ఎగతాళి లెక్కింపులో గుర్తించిన లోపాలను ఎంపిక చేసిన వ్యక్తులకు తెలియజేయాలి.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 548, 83),
('జాతీయ గ్రామీణ ఆరోగ్య మిషన్ కింద కార్యకలాపాల పర్యవేక్షణ', 'జాతీయ గ్రామీణ ఆరోగ్య మిషన్ కింద ఉన్న ఆరోగ్య కేంద్రాల కార్యకలాపాలను పర్యవేక్షించడానికి మార్గదర్శక సూచనలు జారీ చేశారు. ప్రతి ఆరోగ్య కేంద్రం వార్షికంలో కనీసం నాలుగుసార్లు పరిశీలనకు ఎదురుపడాలి, అవి నిర్వహించే కార్యకలాపాలు, జన స్పందన, సరుగ్గా చేయబడిన విషయాలు మరియు ఆరోగ్య ప్రజా సేవల నిర్వహణకు సంబంధించిన వివరాలను సేకరించాలి. సర్వే ప్రక్రియలో గ్రామంలోని ప్రతి ఇంటిని కూడా దర్శించాలి, సాధారణ స్థితిని తెలుసుకోవడం లేదా గుర్తించడం ఈ పర్యవేక్షణ ముఖ్య ఉద్దేశం. అర్హులైన వారికి ఆరోగ్య పరీక్షలు, మందులు, ఆరోగ్య శిక్షణ మరియు ఇతర సేవలు అందించాలి. ఆరోగ్య కేంద్రాల్లో ప్రభుత్వ ఆరోగ్య సహాయకులు నిర్వహించే కార్యకలాపాలను కూడా పరిశీలించాలి.', 'TE', 'GENERAL', 'MEDIUM', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 546, 74),
('బాధ్యతల బదిలీ గురించి శాఖాధికారులకు సూచనలు', 'రాష్ట్ర సర్కారు గతంలో జారీ చేసిన ఆదేశాల ప్రకారం శాఖాధికారుల బాధ్యతలను బదిలీ చేసే నిబంధనలు నవీకరించబడింది. నిర్ణయార్థ నిర్వహణకు అనుబంధంగా, శాఖాధికారుల పనితీరు, బదిలీ మరియు అన్యాయ నిర్వహణకు సంబంధించిన సమస్యలను పరిష్కరించడం కోసం ఒక కమిటీ ఏర్పాటు చేయబడింది. ఈ కమిటీలో ఉపాధి, విద్యా, ఆరోగ్యం మరియు ఇతర విభాగాల శాఖాధికారులు సభ్యులుగా ఉంటారు. బదిలీ ఆదేశం జారీ చేసే ముందు అధికారి యొక్క సర్వీసు రికార్డు, ప్రవర్తన మరియు అన్ని సంబంధిత ఫిర్యాదులను పరిశీలించాలి. కమిటీ ఆరు నెలలకు ఒకసారి సమావేశమవుతుంది. బదిలీ ఆదేశం ఇవ్వడంలో విలంబం ఉంటే కారణం లేఖితంగా తెలియజేయాలి.', 'TE', 'GENERAL', 'HARD', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 483, 69),
('వార్షిక ఆదాయ వివర ప్రకటన', 'రాష్ట్ర పన్ను శాఖ సంవత్సరం వివరాలను ప్రకటిస్తోంది. ప్రతి నిర్మాణ సంవత్సరం ప్రారంభంలో, మునుసటి గత సంవత్సరానికి చెందిన ప్రావణాలు, వ్యయాలు మరియు సంపూర్ణ సమాచారం ఇందుకు జతచేయాలి. వార్షిక ప్రకటనలో గత సంవత్సరం ప్రభుత్వ ఆదాయం ఎంత, ఖర్చు ఎంత, ఆదాయంలో ఏ కార్యక్రమాలకు ఎంత ఖర్చు అయింది, భవిష్యత్ అవసరాల కోసం నిల్వ ఉంచిన సరుకు ఎంత, ఉద్యోగుల జీవన వ్యయాలకు చెల్లించిన సొమ్ము ఎంత అనే వివరాలు ఉండాలి. సమాచార హక్కు కార్యక్రమం ప్రకారం ఈ వివరాలు జారీ చేయాలి. ప్రజలకు అందుబాటులో ఉంచాలి. సమాచార హక్కు కార్యక్రమం కింద ఈ వివరాలను అందించాలంటే కొన్ని ఆధారాలు మాత్రమే తీసివేయాలి. అధికారిక ఇచ్చిన సమాచారాన్ని వినియోగించాలంటే ఆధారాలు ఏవో గుర్తించాలి.', 'TE', 'GENERAL', 'HARD', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 543, 81),
('పార్లమెంటరీ విధాన సవరణ గురించి ప్రకటన', 'జిల్లా ప్రజా సంఘాల కార్యకలాపాలను మరింత బలపరచడానికి జిల్లా అధికారి ఒక కార్యక్రమాన్ని ప్రారంభించారు. సంఘాల్లో సభ్యత్వం, నిర్వహణ, భద్రతా నిధుల నిర్వహణ, ప్రజా సమాచారం మరియు ప్రజా సంఘాల జవాబుదారీ గురించి ఈ కార్యక్రమం ప్రధానంగా దృష్టి పెడుతుంది. ప్రతి సంఘం సంవత్సరానికి ఒకసారి ఆర్థిక నిధుల లెక్కలు సమర్పించాలి, ఏ నిధులు వచ్చాయో, ఎక్కడ వాటిని వినియోగించారో, ఏ నిధులు మిగిలి ఉన్నాయో వివరించాలి. జిల్లా స్థాయి సమీక్ష సంఘం సంవత్సరానికి ఒకసారి సమావేశమై జిల్లా అధికారికి నివేదిక ఇవ్వాలి. సమీక్ష సంఘం సభ్యుల నిర్వహణను, వారి లెక్కలను, వారు చేసిన కార్యకలాపాలను అధ్యయనం చేస్తుంది. ఈ నివేదికపై జిల్లా అధికారి ఆధారంగా చర్చ జరిగి, తగిన సూచనలు ఇవ్వబడతాయి.', 'TE', 'GENERAL', 'HARD', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 556, 80),
('జిల్లా స్థాయి వినోద సభలు', 'జిల్లా ప్రజా వినోద సభలు జరిగే నిర్ణయాల గురించి సమాచారం ఇస్తాయి. ప్రజలు సమాచారం ఇవ్వడానికి, వారి వినోదాలను పరిష్కరించేందుకు సబాయీ ఇవ్వడం సర్వహెత్కరించబడుతుంది. వినోద సభలు జిల్లా కేంద్రంలో జరిగినప్పుడు, విభాగం ప్రధాన కార్యాలయంలో జరిగినప్పుడు, సంఘాలు ఏర్పాటు చేసిన ఇంట్లో జరిగినప్పుడు, లేదా గ్రామ సభలో జరిగినప్పుడు జరుగుతాయి. ఒకే నెలలో కనీసం రెండు వినోద సభలు జరిగేలా చేయడం ఈ కార్యక్రమ లక్ష్యం. వినోద సభలో వచ్చే అభ్యర్థనలను ఉమ్మడి పరిశీలనకు సమర్పించాలి, సమాధానం ఇవ్వాలి. ఒక వినోద సభలో పరిష్కరించిన అంశం మరో వినోద సభలో పునఃపరిశీలించబడుతుంది. వినోద సభల్లో అనుసరించిన వ్యవహార ఆధారం చట్టం, నిబంధనలు, స్థానిక సర్పంచ్ లేదా ఆ స్థానంలో చెరువుకునే స్థానిక సంస్థ సమాధికారి ఆమోదించాలి.', 'TE', 'GENERAL', 'HARD', 'Original text written for ExamTyper. Not copied from any exam paper, news article or book.', 588, 83)
